+/** Sales ingredient use and all ledger consumption by item, inclusive UTC days. */
+export function varianceReport(store, from, to) {
+  const totals = new Map();
+  const add = (itemId, field, qty) => {
+    if (!totals.has(itemId)) totals.set(itemId, { itemId, theoretical: 0, actual: 0 });
+    totals.get(itemId)[field] += Math.round(qty * 1000);
+  };
+  const inRange = (at) => {
+    const day = new Date(at).toISOString().slice(0, 10);
+    return day >= from && day <= to;
+  };
+  for (const sale of store.data.sales) {
+    if (!inRange(sale.soldAt)) continue;
+    for (const n of sale.ingredients) add(n.itemId, "theoretical", n.qty);
+  }
+  const batches = new Map(store.data.batches.map((b) => [b.id, b]));
+  for (const movement of store.data.movements) {
+    if (movement.type !== "consume" || movement.qty <= 0 || !inRange(movement.at)) continue;
+    const batch = batches.get(movement.batchId);
+    if (batch) add(batch.itemId, "actual", movement.qty);
+  }
+  return [...totals.values()]
+    .filter((line) => line.theoretical > 0 || line.actual > 0)
+    .sort((a, b) => a.itemId - b.itemId)
+    .map(({ itemId, theoretical, actual }) => ({
+      itemId, theoretical: theoretical / 1000, actual: actual / 1000, variance: (actual - theoretical) / 1000,
+    }));
+}
