+import { memoryStore } from "../db/store.js";
+import { AppError } from "../errors.js";
+import { t } from "../i18n/messages.js";
+import { getDish } from "./menu.js";
+import { getRecipe, scaled } from "./recipes.js";
+import { consume } from "./batches.js";
+
+/** Imports validated sales rows on a copy, committing only when every row succeeds. */
+export function importSalesRows(store, rows) {
+  const staged = memoryStore(store.data);
+  const known = new Set(staged.data.sales.map((s) => s.ticket));
+  const tickets = new Set();
+  let dishes = 0;
+  for (const { row, ...sale } of rows) {
+    try {
+      const recipe = getRecipe(staged, getDish(staged, sale.dishId).recipeId);
+      const ingredients = scaled(recipe, sale.qty);
+      if (ingredients.some((n) => !Number.isFinite(n.qty) || n.qty < 0)) throw new AppError("invalid_qty");
+      if (known.has(sale.ticket)) continue;
+      for (const n of ingredients) {
+        if (n.qty > 0) consume(staged, n.itemId, n.qty, { at: sale.soldAt, ref: `sale:${sale.ticket}` });
+      }
+      staged.data.sales.push({ id: staged.nextId("sale"), ...sale, ingredients });
+      tickets.add(sale.ticket);
+      dishes += sale.qty;
+    } catch (error) {
+      if (!(error instanceof AppError)) throw error;
+      throw new AppError("bad_request", { reason: `row ${row}: ${t(error.code, "en", error.params)}` });
+    }
+  }
+  store.data = staged.data;
+  return { tickets: tickets.size, dishes };
+}
