+++ b/src/io/sales-import.js
@@ -0,0 +1,35 @@
+import { AppError } from "../errors.js";
+import { isDate } from "../dates.js";
+import { parseCsv } from "./csv.js";
+import { importSalesRows } from "../domain/sales.js";
+
+const HEADER = ["ticket", "soldAt", "dishId", "qty"];
+const CSV_LINE = /^(?:"(?:[^"]|"")*"|[^",]*)(?:,(?:"(?:[^"]|"")*"|[^",]*))*$/;
+const INSTANT = /^\d{4}-\d{2}-\d{2}T(?:[01]\d|2[0-3]):[0-5]\d:[0-5]\d(?:\.\d+)?(?:Z|[+-](?:[01]\d|2[0-3]):[0-5]\d)$/;
+
+/** Validates a sales CSV and atomically imports its previously unseen tickets. */
+export function importSales(store, text) {
+  if (typeof text !== "string") throw new AppError("bad_request", { reason: "csv must be text" });
+  const lines = text.split(/\r?\n/);
+  const fail = (row, reason) => { throw new AppError("bad_request", { reason: `row ${row}: ${reason}` }); };
+  const header = parseCsv(lines[0])[0]?.map((v) => v.trim()) ?? [];
+  if (!CSV_LINE.test(lines[0]) || header.length !== HEADER.length || HEADER.some((k) => !header.includes(k)))
+    fail(1, "expected columns ticket,soldAt,dishId,qty");
+  const rows = [];
+  for (let i = 1; i < lines.length; i++) {
+    if (!lines[i].trim()) continue;
+    if (!CSV_LINE.test(lines[i])) fail(i + 1, "invalid CSV");
+    const fields = parseCsv(lines[i])[0];
+    if (fields.length !== header.length) fail(i + 1, "wrong number of columns");
+    const r = Object.fromEntries(header.map((k, j) => [k, fields[j].trim()]));
+    if (!r.ticket) fail(i + 1, "ticket is required");
+    if (!INSTANT.test(r.soldAt) || !isDate(r.soldAt.slice(0, 10)) || !Number.isFinite(Date.parse(r.soldAt)))
+      fail(i + 1, "soldAt must be an ISO instant");
+    if (!/^\d+$/.test(r.dishId) || !Number.isSafeInteger(Number(r.dishId)) || Number(r.dishId) < 1)
+      fail(i + 1, "dishId must be a positive integer");
+    if (!/^\d+$/.test(r.qty) || !Number.isSafeInteger(Number(r.qty)) || Number(r.qty) < 1)
+      fail(i + 1, "qty must be a positive integer");
+    rows.push({ ticket: r.ticket, soldAt: new Date(r.soldAt).toISOString(), dishId: Number(r.dishId), qty: Number(r.qty), row: i + 1 });
+  }
+  return importSalesRows(store, rows);
+}
